<script>
  // @ts-nocheck
  let { producto = null, proveedores = [], alGuardar, alCancelar } = $props();
  let datos = $state(producto ? { ...producto, codigo_barras: producto.id_producto } : { descripcion: '', codigo_barras: '', precio_venta: 0, cantidad_disponible: 0, stock_minimo: 5, id_proveedor: '' });
  let error = $state(''); let guardando = $state(false);
  async function guardar(){guardando=true;error='';try{const cuerpo={...datos,id_proveedor:datos.id_proveedor ? Number(datos.id_proveedor) : undefined};await alGuardar(cuerpo,producto?.id_producto); }catch(e){error=e.message}finally{guardando=false}}
</script>
<div class="dialog-backdrop"><section class="dialog"><h3 class="dialog-title">{producto ? 'Editar producto' : 'Nuevo producto'}</h3><div class="campos"><label class="field"><span>Nombre</span><input class="input" bind:value={datos.descripcion} /></label><label class="field"><span>Código</span><input class="input" bind:value={datos.codigo_barras} disabled={!!producto} /></label><label class="field"><span>Precio</span><input class="input" type="number" bind:value={datos.precio_venta} /></label><label class="field"><span>Stock</span><input class="input" type="number" bind:value={datos.cantidad_disponible} /></label><label class="field"><span>Stock mínimo</span><input class="input" type="number" bind:value={datos.stock_minimo} /></label><label class="field"><span>Proveedor</span><select class="input" bind:value={datos.id_proveedor}><option value="">Sin proveedor</option>{#each proveedores as p}<option value={p.id_proveedor}>{p.nombre}</option>{/each}</select></label></div>{#if error}<p class="error">{error}</p>{/if}<div class="dialog-actions"><button class="btn btn-secondary" onclick={alCancelar}>Cancelar</button><button class="btn btn-primary" onclick={guardar} disabled={guardando}>{guardando ? 'Guardando…' : 'Guardar'}</button></div></section></div><style>.campos{display:grid;grid-template-columns:1fr 1fr;gap:12px}.error{color:var(--color-peligro)}</style>
